import { useState } from 'react'; import { Check, ChevronRight } from 'lucide-react'; import { IndustrialHeader } from './IndustrialHeader';
const IMG_ONDERDELENKIT = 'data:image/jpeg;base64,';
interface Props{onComplete:()=>void;elapsedTime:number;toProduct:string;operatorSettings:{operatorName:string;line:string;station:string};onBack:()=>void;onSettings?:()=>void}
export function ChangeoverStep3Screen({onComplete,elapsedTime,toProduct,operatorSettings,onBack,onSettings}:Props){
  const partsList = toProduct === 'Product 1'
    ? [
        {id:1,label:'1 × dwarsprofiel 370×60 mm (voorbereid)'},
        {id:2,label:'2 × langsprofiel 630×30 mm'},
        {id:3,label:'4 × wielen zonder rem'},
        {id:4,label:'Lange Nutensteinen'},
        {id:5,label:'M3 T-moeren'},
        {id:6,label:'Benodigde M3-bouten'},
        {id:7,label:'1 × handvat + M5-bout'},
      ]
    : [
        {id:1,label:'1 × dwarsprofiel 630×30 mm (voorbereid)'},
        {id:2,label:'2 × langsprofiel 370×30 mm'},
        {id:3,label:'4 × wielen met rem'},
        {id:4,label:'Lange Nutensteinen'},
        {id:5,label:'M3 T-moeren'},
        {id:6,label:'Benodigde M3-bouten'},
      ];

  const [parts,setParts]=useState(partsList.map(p=>({...p,checked:false})));
  const toggle=(id:number)=>setParts(p=>p.map(i=>i.id===id?{...i,checked:!i.checked}:i));
  const all=parts.every(i=>i.checked);

  return <div className="h-full min-h-0 flex flex-col bg-gray-100 overflow-hidden"><IndustrialHeader title="Omstelling, stap 3 van 5" subtitle={`Onderdelen ${toProduct} controleren`} showTimer elapsedTime={elapsedTime} operatorSettings={operatorSettings} onBack={onBack} onSettings={onSettings}/><div className="flex-1 min-h-0 overflow-y-auto flex flex-col md:flex-row p-8 gap-8 max-w-[1280px] mx-auto w-full"><div className="flex-1 bg-white rounded-lg shadow-sm border border-gray-200 p-6"><img src={IMG_ONDERDELENKIT} alt="Onderdelenkit" className="w-full h-full min-h-72 object-cover rounded-lg"/></div><div className="w-full md:w-96 flex flex-col gap-5"><div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6"><h3 className="text-2xl text-gray-800 font-bold mb-3 uppercase">Controleer onderdelenkit</h3><p className="text-sm text-gray-700">De waterspider heeft alle onderdelen voor {toProduct} klaargezet.</p></div><div className="bg-white rounded-lg shadow-sm border border-gray-200 p-5"><h4 className="text-xs uppercase tracking-wider text-gray-500 mb-4 font-medium">Onderdelen lijst</h4>{parts.map(part=><label key={part.id} className="flex items-center gap-3 p-3 bg-gray-50 rounded mb-2"><input type="checkbox" checked={part.checked} onChange={()=>toggle(part.id)} className="w-6 h-6"/><span className="text-sm text-gray-800 flex-1">{part.label}</span>{part.checked&&<Check className="w-5 h-5 text-green-600"/>}</label>)}</div><button onClick={onComplete} disabled={!all} className={`w-full text-lg py-4 px-6 rounded-lg flex items-center justify-center gap-3 font-medium ${all?'bg-blue-500 text-white':'bg-gray-300 text-gray-500'}`}>Onderdelen compleet<ChevronRight className="w-6 h-6"/></button></div></div></div>;
}
